import java.util.EnumMap
import java.util.EnumSet
import java.util.HashMap
import java.util.HashSet

enum class Status { ACTIVE, INACTIVE }
class Bad {
    val statusMap: HashMap<Status, String> = HashMap() // bad
    val statusSet: HashSet<Status> = HashSet() // bad
}
class Good {
    val statusMap: EnumMap<Status, String> = EnumMap(Status::class.java)
    val statusSet: EnumSet<Status> = EnumSet.allOf(Status::class.java)
}

